//! Selector strings generated by `get_by_*` locators, ported from
//! Playwright's `isomorphic/locatorUtils.ts` and `isomorphic/stringUtils.ts`
//! (the generated strings match Playwright byte for byte).

#![allow(dead_code)]

use std::fmt;
use std::sync::OnceLock;

use regex::Regex;
use serde::Serialize;

use crate::js::JsValue;

/// A JavaScript regular expression, evaluated by the browser.
///
/// The source uses JavaScript syntax (not Rust's `regex` syntax) because the
/// matching happens in the page. Its [`Display`](fmt::Display) form is the
/// one of JavaScript's `String(re)`, e.g. `/hello\/world/i`.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct JsRegex {
    source: String,
    flags: String,
}

/// Shorthand for [`JsRegex::new`]: `regex("hello", "i")` is `/hello/i`.
pub fn regex(source: impl AsRef<str>, flags: impl AsRef<str>) -> JsRegex {
    JsRegex::new(source, flags)
}

const FLAG_ORDER: &str = "dgimsuvy";

impl JsRegex {
    /// The equivalent Rust regular expression (flags `i`, `m` and `s`), if
    /// the source is supported by the `regex` crate.
    pub(crate) fn to_regex(&self) -> Option<Regex> {
        regex::RegexBuilder::new(&self.source.replace(r"\/", "/"))
            .case_insensitive(self.flags.contains('i'))
            .multi_line(self.flags.contains('m'))
            .dot_matches_new_line(self.flags.contains('s'))
            .build()
            .ok()
    }

    /// A regular expression with JavaScript `source` and `flags`
    /// (any of `dgimsuvy`; other characters are ignored).
    pub fn new(source: impl AsRef<str>, flags: impl AsRef<str>) -> Self {
        let flags = flags.as_ref();
        let flags: String = FLAG_ORDER.chars().filter(|c| flags.contains(*c)).collect();
        JsRegex {
            source: normalize_regex_source(source.as_ref()),
            flags,
        }
    }

    /// The source, normalised like JavaScript's `RegExp.prototype.source`.
    pub fn source(&self) -> &str {
        &self.source
    }

    /// The flags, in JavaScript's canonical order.
    pub fn flags(&self) -> &str {
        &self.flags
    }

    fn is_unicode(&self) -> bool {
        self.flags.contains('u') || self.flags.contains('v')
    }
}

/// Mirrors V8's `EscapeRegExpSource`: unescaped `/` outside character
/// classes and line terminators are escaped, the empty source is `(?:)`.
fn normalize_regex_source(source: &str) -> String {
    if source.is_empty() {
        return "(?:)".to_string();
    }
    let mut out = String::with_capacity(source.len());
    let mut in_class = false;
    let mut chars = source.chars();
    let push_char = |out: &mut String, c: char| match c {
        '\n' => out.push_str("\\n"),
        '\r' => out.push_str("\\r"),
        '\u{2028}' => out.push_str("\\u2028"),
        '\u{2029}' => out.push_str("\\u2029"),
        c => out.push(c),
    };
    while let Some(c) = chars.next() {
        match c {
            '\\' => match chars.next() {
                Some('\n') => out.push_str("\\n"),
                Some('\r') => out.push_str("\\r"),
                Some('\u{2028}') => out.push_str("\\u2028"),
                Some('\u{2029}') => out.push_str("\\u2029"),
                Some(next) => {
                    out.push('\\');
                    out.push(next);
                }
                None => out.push('\\'),
            },
            '/' if !in_class => out.push_str("\\/"),
            '[' => {
                in_class = true;
                out.push(c);
            }
            ']' => {
                in_class = false;
                out.push(c);
            }
            c => push_char(&mut out, c),
        }
    }
    out
}

impl fmt::Display for JsRegex {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "/{}/{}", self.source, self.flags)
    }
}

impl Serialize for JsRegex {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        JsValue::RegExp {
            source: self.source.clone(),
            flags: self.flags.clone(),
        }
        .serialize(serializer)
    }
}

impl From<Regex> for JsRegex {
    fn from(re: Regex) -> Self {
        JsRegex::from(&re)
    }
}

impl From<&Regex> for JsRegex {
    /// Converts a leading inline flag group (`(?i)`, `(?ms)`, ...) into
    /// JavaScript flags; the rest is used as the JavaScript source.
    fn from(re: &Regex) -> Self {
        let pattern = re.as_str();
        static INLINE: OnceLock<Regex> = OnceLock::new();
        let inline = INLINE.get_or_init(|| Regex::new(r"^\(\?([a-zA-Z]+)\)").unwrap());
        if let Some(m) = inline.captures(pattern) {
            let group = m.get(1).unwrap().as_str();
            let flags: String = group
                .chars()
                .filter(|c| matches!(c, 'i' | 'm' | 's'))
                .collect();
            return JsRegex::new(&pattern[m.get(0).unwrap().end()..], flags);
        }
        JsRegex::new(pattern, "")
    }
}

/// Text to match: a string (substring/exact match depending on the
/// method) or a JavaScript regular expression.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TextMatch {
    /// A string.
    Text(String),
    /// A regular expression.
    Regex(JsRegex),
}

impl From<&str> for TextMatch {
    fn from(s: &str) -> Self {
        TextMatch::Text(s.to_string())
    }
}

impl From<String> for TextMatch {
    fn from(s: String) -> Self {
        TextMatch::Text(s)
    }
}

impl From<&String> for TextMatch {
    fn from(s: &String) -> Self {
        TextMatch::Text(s.clone())
    }
}

impl From<JsRegex> for TextMatch {
    fn from(re: JsRegex) -> Self {
        TextMatch::Regex(re)
    }
}

impl From<&JsRegex> for TextMatch {
    fn from(re: &JsRegex) -> Self {
        TextMatch::Regex(re.clone())
    }
}

impl From<Regex> for TextMatch {
    fn from(re: Regex) -> Self {
        TextMatch::Regex(re.into())
    }
}

impl From<&Regex> for TextMatch {
    fn from(re: &Regex) -> Self {
        TextMatch::Regex(re.into())
    }
}

impl Serialize for TextMatch {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            TextMatch::Text(s) => serializer.serialize_str(s),
            TextMatch::Regex(re) => re.serialize(serializer),
        }
    }
}

// ----------------------------------------------------------------------
// stringUtils.ts
// ----------------------------------------------------------------------

/// `JSON.stringify` of a string.
pub(crate) fn json_string(s: &str) -> String {
    serde_json::to_string(s).expect("strings always serialize")
}

/// `escapeWithQuotes` (only for generated code, never for selectors).
pub(crate) fn escape_with_quotes(text: &str, quote: char) -> String {
    let stringified = json_string(text);
    let escaped = stringified[1..stringified.len() - 1].replace("\\\"", "\"");
    match quote {
        '\'' => format!("'{}'", escaped.replace('\'', "\\'")),
        '"' => format!("\"{}\"", escaped.replace('"', "\\\"")),
        '`' => format!("`{}`", escaped.replace('`', "\\`")),
        _ => panic!("Invalid escape char"),
    }
}

/// `normalizeEscapedRegexQuotes`: reverses [`escape_regex_for_selector`].
pub(crate) fn normalize_escaped_regex_quotes(source: &str) -> String {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| Regex::new(r#"(^|[^\\])(\\\\)*\\(['"`])"#).unwrap());
    re.replace_all(source, "${1}${2}${3}").into_owned()
}

/// `escapeRegexForSelector`.
pub(crate) fn escape_regex_for_selector(re: &JsRegex) -> String {
    // Unicode mode does not allow "identity character escapes", so we do
    // not escape and hope that it does not contain quotes and/or >> signs.
    if re.is_unicode() {
        return re.to_string();
    }
    static RE: OnceLock<Regex> = OnceLock::new();
    let quotes = RE.get_or_init(|| Regex::new(r#"(^|[^\\])(\\\\)*(["'`])"#).unwrap());
    quotes
        .replace_all(&re.to_string(), "${1}${2}\\${3}")
        .replace(">>", "\\>\\>")
}

/// `escapeForTextSelector`.
pub(crate) fn escape_for_text_selector(text: &TextMatch, exact: bool) -> String {
    match text {
        TextMatch::Regex(re) => escape_regex_for_selector(re),
        TextMatch::Text(s) => format!("{}{}", json_string(s), if exact { 's' } else { 'i' }),
    }
}

/// `escapeForAttributeSelector`.
pub(crate) fn escape_for_attribute_selector(value: &TextMatch, exact: bool) -> String {
    match value {
        TextMatch::Regex(re) => escape_regex_for_selector(re),
        TextMatch::Text(s) => format!(
            "\"{}\"{}",
            s.replace('\\', "\\\\").replace('"', "\\\""),
            if exact { 's' } else { 'i' }
        ),
    }
}

