/// Options of `get_by_role`, as used to build the selector.
#[derive(Debug, Clone, Default)]
pub(crate) struct ByRoleOptions {
    pub(crate) checked: Option<bool>,
    pub(crate) disabled: Option<bool>,
    pub(crate) selected: Option<bool>,
    pub(crate) expanded: Option<bool>,
    pub(crate) include_hidden: Option<bool>,
    pub(crate) level: Option<i64>,
    pub(crate) name: Option<TextMatch>,
    pub(crate) description: Option<TextMatch>,
    pub(crate) pressed: Option<bool>,
    pub(crate) exact: Option<bool>,
}

fn get_by_attribute_text_selector(attr_name: &str, text: &TextMatch, exact: bool) -> String {
    format!(
        "internal:attr=[{attr_name}={}]",
        escape_for_attribute_selector(text, exact)
    )
}

/// Multiple test id attribute names can be joined with a comma.
#[allow(dead_code)]
pub(crate) fn split_test_id_attribute_names(test_id_attribute_name: &str) -> Vec<String> {
    test_id_attribute_name
        .split(',')
        .map(str::to_string)
        .collect()
}

/// `encodeTestIdAttributeName`.
pub(crate) fn encode_test_id_attribute_name(test_id_attribute_name: &str) -> String {
    if test_id_attribute_name.contains(',') {
        json_string(test_id_attribute_name)
    } else {
        test_id_attribute_name.to_string()
    }
}

/// `getByTestIdSelector`.
pub(crate) fn get_by_test_id_selector(test_id_attribute_name: &str, test_id: &TextMatch) -> String {
    format!(
        "internal:testid=[{}={}]",
        encode_test_id_attribute_name(test_id_attribute_name),
        escape_for_attribute_selector(test_id, true)
    )
}

/// `getByLabelSelector`.
pub(crate) fn get_by_label_selector(text: &TextMatch, exact: bool) -> String {
    format!("internal:label={}", escape_for_text_selector(text, exact))
}

/// `getByAltTextSelector`.
pub(crate) fn get_by_alt_text_selector(text: &TextMatch, exact: bool) -> String {
    get_by_attribute_text_selector("alt", text, exact)
}

/// `getByTitleSelector`.
pub(crate) fn get_by_title_selector(text: &TextMatch, exact: bool) -> String {
    get_by_attribute_text_selector("title", text, exact)
}

/// `getByPlaceholderSelector`.
pub(crate) fn get_by_placeholder_selector(text: &TextMatch, exact: bool) -> String {
    get_by_attribute_text_selector("placeholder", text, exact)
}

/// `getByTextSelector`.
pub(crate) fn get_by_text_selector(text: &TextMatch, exact: bool) -> String {
    format!("internal:text={}", escape_for_text_selector(text, exact))
}

/// `getByRoleSelector`.
pub(crate) fn get_by_role_selector(role: &str, options: &ByRoleOptions) -> String {
    let mut props: Vec<(&str, String)> = Vec::new();
    if let Some(v) = options.checked {
        props.push(("checked", v.to_string()));
    }
    if let Some(v) = options.disabled {
        props.push(("disabled", v.to_string()));
    }
    if let Some(v) = options.selected {
        props.push(("selected", v.to_string()));
    }
    if let Some(v) = options.expanded {
        props.push(("expanded", v.to_string()));
    }
    if let Some(v) = options.include_hidden {
        props.push(("include-hidden", v.to_string()));
    }
    if let Some(v) = options.level {
        props.push(("level", v.to_string()));
    }
    let exact = options.exact.unwrap_or(false);
    if let Some(name) = &options.name {
        props.push(("name", escape_for_attribute_selector(name, exact)));
    }
    if let Some(description) = &options.description {
        props.push((
            "description",
            escape_for_attribute_selector(description, exact),
        ));
    }
    if let Some(v) = options.pressed {
        props.push(("pressed", v.to_string()));
    }
    let mut out = format!("internal:role={role}");
    for (n, v) in props {
        out.push_str(&format!("[{n}={v}]"));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn t(s: &str) -> TextMatch {
        s.into()
    }

    #[test]
    fn regex_display_matches_javascript() {
        assert_eq!(regex("Hello", "").to_string(), "/Hello/");
        assert_eq!(regex("", "").to_string(), "/(?:)/");
        assert_eq!(regex("a/b", "").to_string(), "/a\\/b/");
        assert_eq!(regex("a\\/b", "").to_string(), "/a\\/b/");
        assert_eq!(regex("[/]", "").to_string(), "/[/]/");
        assert_eq!(regex("a\nb", "").to_string(), "/a\\nb/");
        assert_eq!(regex("x", "smi").to_string(), "/x/ims");
        assert_eq!(regex("x", "yvgd").to_string(), "/x/dgvy");
    }

    #[test]
    fn regex_from_rust_regex() {
        let re = JsRegex::from(Regex::new("(?i)hello world").unwrap());
        assert_eq!(re.to_string(), "/hello world/i");
        let re = JsRegex::from(Regex::new("(?ms)a.b").unwrap());
        assert_eq!(re.to_string(), "/a.b/ms");
        let re = JsRegex::from(Regex::new("a.b").unwrap());
        assert_eq!(re.to_string(), "/a.b/");
    }

    #[test]
    fn regex_serializes_like_playwright() {
        let v = serde_json::to_value(regex("a", "i")).unwrap();
        assert_eq!(v, serde_json::Value::String("/a/i".into()));
    }

    #[test]
    fn escape_with_quotes_works() {
        assert_eq!(escape_with_quotes("He\"llo", '\''), "'He\"llo'");
        assert_eq!(escape_with_quotes("it's", '\''), "'it\\'s'");
        assert_eq!(escape_with_quotes("a\nb", '\''), "'a\\nb'");
        assert_eq!(escape_with_quotes("a\"b", '"'), "\"a\\\"b\"");
    }

    #[test]
    fn get_by_selectors() {
        assert_eq!(
            get_by_text_selector(&t("Hello"), false),
            "internal:text=\"Hello\"i"
        );
        assert_eq!(
            get_by_text_selector(&t("Hello"), true),
            "internal:text=\"Hello\"s"
        );
        assert_eq!(
            get_by_text_selector(&regex("Hello", "").into(), false),
            "internal:text=/Hello/"
        );
        assert_eq!(
            get_by_label_selector(&t("Name"), false),
            "internal:label=\"Name\"i"
        );
        assert_eq!(
            get_by_placeholder_selector(&t("he\"l\\lo"), true),
            "internal:attr=[placeholder=\"he\\\"l\\\\lo\"s]"
        );
        assert_eq!(
            get_by_alt_text_selector(&t("x"), false),
            "internal:attr=[alt=\"x\"i]"
        );
        assert_eq!(
            get_by_title_selector(&t("x"), false),
            "internal:attr=[title=\"x\"i]"
        );
        assert_eq!(
            get_by_test_id_selector("data-testid", &t("Hello")),
            "internal:testid=[data-testid=\"Hello\"s]"
        );
        assert_eq!(
            get_by_test_id_selector("a,b", &t("Hello")),
            "internal:testid=[\"a,b\"=\"Hello\"s]"
        );
        assert_eq!(
            get_by_role_selector("button", &ByRoleOptions::default()),
            "internal:role=button"
        );
        let options = ByRoleOptions {
            checked: Some(true),
            pressed: Some(false),
            level: Some(3),
            name: Some(t("He\"llo")),
            exact: Some(true),
            include_hidden: Some(true),
            ..Default::default()
        };
        assert_eq!(
            get_by_role_selector("button", &options),
            "internal:role=button[checked=true][include-hidden=true][level=3][name=\"He\\\"llo\"s][pressed=false]"
        );
    }

    #[test]
    fn regex_escaping_for_selectors() {
        // getByText(/He"llo/)
        assert_eq!(
            escape_for_text_selector(&regex("He\"llo", "").into(), false),
            "/He\\\"llo/"
        );
        // getByText(/He\\"llo/)
        assert_eq!(
            escape_for_text_selector(&regex("He\\\\\"llo", "").into(), false),
            "/He\\\\\\\"llo/"
        );
        assert_eq!(
            escape_for_text_selector(&regex("a>>b", "").into(), false),
            "/a\\>\\>b/"
        );
        // Unicode regexes are not escaped.
        assert_eq!(
            escape_for_text_selector(&regex("a\"b", "u").into(), false),
            "/a\"b/u"
        );
        assert_eq!(normalize_escaped_regex_quotes("/He\\\"llo/"), "/He\"llo/");
        assert_eq!(
            normalize_escaped_regex_quotes("/He\\\\\\\"llo/"),
            "/He\\\\\"llo/"
        );
    }
}
